import type { SupabaseClient } from '@supabase/supabase-js'

import { createRowOps } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/supabase-rows'
import { createStorageOps } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/supabase-storage'
import type {
  AuthConfig,
  LogsResult,
  PlatformAdapter,
  Secret,
  Suggestion,
  UserRecord,
} from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/types'
import {
  createManagementApiClient,
  type ManagementApiClient,
} from '@/registry/default/platform/platform-kit-nextjs/lib/management-api'

export interface ManagementTransport {
  /** Base URL of the consumer's Management API proxy (token injected server-side). */
  baseUrl: string
  /** Project ref for Management API calls; defaults to the adapter's projectRef. */
  projectRef?: string
  headers?: Record<string, string>
  fetch?: typeof fetch
}

export interface CreateSupabaseAdapterOptions {
  /** supabase-js client — the data/auth/storage plane. */
  supabase: SupabaseClient
  /** Project ref, used for introspection identity and the dashboard link. */
  projectRef?: string
  /**
   * Optional Management API transport. When provided, the auth-config, logs,
   * secrets, advisors, and SQL-editor features light up. Without it the adapter
   * is fully client-side (supabase-js only).
   */
  management?: ManagementTransport
  /** Optional natural-language → SQL generator (consumer's AI endpoint). */
  generateSql?: (prompt: string) => Promise<{ sql: string }>
}

/**
 * Bundled default adapter for classic hosted Supabase.
 *
 * Data, auth-users, and storage run entirely through supabase-js; introspection
 * uses the PostgREST OpenAPI spec. Management-only features are opt-in via a
 * `management` transport the consumer supplies (the kit ships no proxy).
 */
export function createSupabaseAdapter(opts: CreateSupabaseAdapterOptions): PlatformAdapter {
  const { supabase } = opts
  const rows = createRowOps(supabase)
  const storage = createStorageOps(supabase)

  const hasManagement = !!opts.management
  const ref = opts.management?.projectRef ?? opts.projectRef

  let mgmt: ManagementApiClient | null = null
  if (opts.management) {
    mgmt = createManagementApiClient({
      baseUrl: opts.management.baseUrl,
      headers: opts.management.headers,
      fetch: opts.management.fetch,
    })
  }

  const adapter: PlatformAdapter = {
    projectRef: opts.projectRef,
    features: {
      introspection: true,
      tableRows: true,
      authConfig: hasManagement,
      authUsers: true,
      storage: true,
      logs: hasManagement,
      secrets: hasManagement,
      advisors: hasManagement,
      runSql: hasManagement,
      naturalLanguageSql: !!opts.generateSql && hasManagement,
      rlsPolicies: hasManagement,
    },

    async listTables(schemas?: string[]) {
      const { introspectViaPostgrest } =
        await import('@/registry/default/platform/platform-kit-nextjs/lib/introspection/postgrest')
      const tables = await introspectViaPostgrest(supabase)
      if (schemas && schemas.length > 0) {
        return tables.filter((t) => schemas.includes(t.schema))
      }
      return tables
    },

    selectRows: rows.selectRows,
    updateRow: rows.updateRow,
    insertRow: rows.insertRow,
    deleteRow: rows.deleteRow,

    listBuckets: storage.listBuckets,
    listObjects: storage.listObjects,

    async listUsers({ page = 1, perPage = 100 } = {}) {
      const { data, error } = await supabase.auth.admin.listUsers({ page, perPage })
      if (error) throw error
      return {
        users: (data?.users ?? []) as UserRecord[],
        total: (data as any)?.total ?? null,
      }
    },

    async userCountsByDay(days: number) {
      // Aggregate created_at across admin.listUsers pages, bounded to avoid
      // runaway fetches on very large projects.
      const now = new Date()
      const start = new Date(now)
      start.setUTCDate(start.getUTCDate() - (days - 1))
      start.setUTCHours(0, 0, 0, 0)

      const counts = new Map<string, number>()
      const perPage = 1000
      const maxPages = 10
      for (let page = 1; page <= maxPages; page++) {
        const { data, error } = await supabase.auth.admin.listUsers({ page, perPage })
        if (error) throw error
        const users = data?.users ?? []
        for (const u of users) {
          if (!u.created_at) continue
          const created = new Date(u.created_at)
          if (created < start) continue
          const key = created.toISOString().slice(0, 10)
          counts.set(key, (counts.get(key) ?? 0) + 1)
        }
        if (users.length < perPage) break
      }

      const series: { date: string; users: number }[] = []
      for (let i = 0; i < days; i++) {
        const d = new Date(start)
        d.setUTCDate(start.getUTCDate() + i)
        const key = d.toISOString().slice(0, 10)
        series.push({ date: key, users: counts.get(key) ?? 0 })
      }
      return series
    },

    dashboardUrl() {
      return opts.projectRef ? `https://supabase.com/dashboard/project/${opts.projectRef}` : null
    },
  }

  if (opts.generateSql) {
    adapter.generateSql = opts.generateSql
  }

  // --- Management-only capabilities ---
  if (mgmt && ref) {
    adapter.getAuthConfig = async (): Promise<AuthConfig> => {
      const { data, error } = await mgmt!.GET('/v1/projects/{ref}/config/auth', {
        params: { path: { ref } },
      })
      if (error) throw error
      return data as AuthConfig
    }

    adapter.updateAuthConfig = async (payload): Promise<AuthConfig> => {
      const { data, error } = await mgmt!.PATCH('/v1/projects/{ref}/config/auth', {
        params: { path: { ref } },
        body: payload as any,
      })
      if (error) throw error
      return data as AuthConfig
    }

    adapter.getLogs = async ({ sql, start, end }): Promise<LogsResult> => {
      const now = new Date()
      const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000)
      const { data, error } = await mgmt!.GET('/v1/projects/{ref}/analytics/endpoints/logs.all', {
        params: {
          path: { ref },
          query: {
            sql,
            iso_timestamp_start: start ?? oneHourAgo.toISOString(),
            iso_timestamp_end: end ?? now.toISOString(),
          },
        },
      })
      if (error) throw error
      return data as LogsResult
    }

    adapter.getSecrets = async (): Promise<Secret[]> => {
      const { data, error } = await mgmt!.GET('/v1/projects/{ref}/secrets', {
        params: { path: { ref } },
      })
      if (error) throw error
      return (data ?? []) as Secret[]
    }

    adapter.createSecrets = async (secrets): Promise<void> => {
      const { error } = await mgmt!.POST('/v1/projects/{ref}/secrets', {
        params: { path: { ref } },
        body: secrets as any,
      })
      if (error) throw error
    }

    adapter.deleteSecrets = async (names): Promise<void> => {
      const { error } = await mgmt!.DELETE('/v1/projects/{ref}/secrets', {
        params: { path: { ref } },
        body: names as any,
      })
      if (error) throw error
    }

    adapter.getAdvisors = async (): Promise<Suggestion[]> => {
      const { data: perfData, error: perfError } = await mgmt!.GET(
        '/v1/projects/{ref}/advisors/performance',
        { params: { path: { ref } } }
      )
      if (perfError) throw perfError
      const { data: secData, error: secError } = await mgmt!.GET(
        '/v1/projects/{ref}/advisors/security',
        { params: { path: { ref } } }
      )
      if (secError) throw secError
      const performance = (perfData?.lints ?? []).map((l: any) => ({
        ...l,
        type: 'performance' as const,
      }))
      const security = (secData?.lints ?? []).map((l: any) => ({
        ...l,
        type: 'security' as const,
      }))
      return [...performance, ...security] as Suggestion[]
    }

    adapter.runSql = async ({ query, readOnly }): Promise<any[]> => {
      const { data, error } = await mgmt!.POST('/v1/projects/{ref}/database/query', {
        params: { path: { ref } },
        body: { query, read_only: readOnly },
      })
      if (error) throw error
      return data as any[]
    }
  }

  return adapter
}

import type { SupabaseClient } from '@supabase/supabase-js'

import { createRowOps } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/supabase-rows'
import { createStorageOps } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/supabase-storage'
import type { PlatformAdapter } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/types'
import {
  mapIntrospectResult,
  type SupaliteIntrospectResult,
} from '@/registry/default/platform/platform-kit-nextjs/lib/introspection/supalite'

export interface CreateSupaliteAdapterOptions {
  /** supabase-js client pointed at the supalite origin. */
  supabase: SupabaseClient
  /** Base URL for `/_system/*` calls. Defaults to the current origin. */
  baseUrl?: string
  /** Mirror of supalite's EXPERIMENTAL_STORAGE flag. */
  enableStorage?: boolean
}

/**
 * Example adapter for supalite (`@supabase/lite`).
 *
 * Data and storage use supabase-js (PostgREST / storage-api). Schema comes from
 * supalite's `GET /_system/introspect`. supalite has no Management API, no
 * arbitrary-SQL endpoint, and no auth-admin, so those features are off.
 */
export function createSupaliteAdapter(opts: CreateSupaliteAdapterOptions): PlatformAdapter {
  const { supabase, enableStorage = false } = opts
  const baseUrl = opts.baseUrl ?? (typeof window !== 'undefined' ? window.location.origin : '')
  const rows = createRowOps(supabase)
  const storage = createStorageOps(supabase)

  const adapter: PlatformAdapter = {
    projectRef: undefined,
    features: {
      introspection: true,
      tableRows: true,
      authConfig: false,
      authUsers: false,
      storage: enableStorage,
      logs: false,
      secrets: false,
      advisors: false,
      runSql: false,
      naturalLanguageSql: false,
      rlsPolicies: false,
    },

    async listTables(schemas?: string[]) {
      const response = await fetch(`${baseUrl}/_system/introspect`)
      if (!response.ok) {
        throw new Error(`Failed to introspect supalite (${response.status}).`)
      }
      const json = (await response.json()) as SupaliteIntrospectResult
      return mapIntrospectResult(json, schemas)
    },

    selectRows: rows.selectRows,
    updateRow: rows.updateRow,
    insertRow: rows.insertRow,
    deleteRow: rows.deleteRow,

    dashboardUrl() {
      return null
    },
  }

  if (enableStorage) {
    adapter.listBuckets = storage.listBuckets
    adapter.listObjects = storage.listObjects
  }

  return adapter
}

/**
 * Thrown by an adapter when a capability is not supported by the current
 * backend (e.g. running arbitrary SQL against supalite). The UI feature-detects
 * via `adapter.features` and should not call unsupported methods, but adapters
 * throw this as a safety net.
 */
export class NotSupportedError extends Error {
  constructor(capability: string) {
    super(`"${capability}" is not supported by this platform adapter.`)
    this.name = 'NotSupportedError'
  }
}

/**
 * Normalized schema-introspection shapes consumed by the UI. Both the classic
 * Supabase adapter (PostgREST OpenAPI) and the supalite adapter
 * (`/_system/introspect`) map their native output into these types so the
 * components stay backend-agnostic.
 */

export interface IntrospectedColumn {
  name: string
  /** Postgres-style data type, e.g. 'text', 'integer', 'boolean', 'ARRAY', 'USER-DEFINED'. */
  data_type: string
  /** Underlying type name (udt); used for display. On supalite this mirrors `data_type`. */
  format: string
  is_nullable: boolean
  is_identity: boolean
  is_generated: boolean
  /** Whether the column can be written to (excludes generated/identity columns). */
  is_updatable: boolean
  default_value: any
  /** Enum members when the column is an enum type; empty otherwise. */
  enums: string[]
  comment: string | null
}

export interface IntrospectedTable {
  /** Stable identifier: pg oid (classic) or `${schema}.${name}` (supalite). */
  id: string | number
  schema: string
  name: string
  columns: IntrospectedColumn[]
  primary_keys: { name: string }[]
  /** Estimated live row count, or null when unavailable (render as "—"). */
  live_rows_estimate: number | null
  /** RLS state, or null when the backend does not expose it (hide RLS UI). */
  rls_enabled: boolean | null
  comment: string | null
}

import type { SupabaseClient } from '@supabase/supabase-js'

import type { SelectRowsResult } from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/types'

/**
 * Table-row CRUD backed by supabase-js `.from()` (PostgREST). Shared by every
 * adapter — the data plane is identical for classic Supabase and supalite.
 *
 * `.schema()` is only invoked for non-default schemas since supalite (SQLite)
 * is single-schema and rejects `.schema()`.
 */
export function createRowOps(supabase: SupabaseClient) {
  const table = (schema: string | undefined, name: string) =>
    schema && schema !== 'public' ? supabase.schema(schema).from(name) : supabase.from(name)

  return {
    async selectRows(opts: {
      schema?: string
      table: string
      limit?: number
      offset?: number
    }): Promise<SelectRowsResult> {
      const limit = opts.limit ?? 100
      const offset = opts.offset ?? 0
      const { data, count, error } = await table(opts.schema, opts.table)
        .select('*', { count: 'exact' })
        .range(offset, offset + limit - 1)
      if (error) throw error
      return { rows: data ?? [], count: count ?? null }
    },

    async updateRow(opts: {
      schema?: string
      table: string
      values: Record<string, any>
      match: Record<string, any>
    }): Promise<void> {
      const { error } = await table(opts.schema, opts.table).update(opts.values).match(opts.match)
      if (error) throw error
    },

    async insertRow(opts: {
      schema?: string
      table: string
      values: Record<string, any>
    }): Promise<void> {
      const { error } = await table(opts.schema, opts.table).insert(opts.values)
      if (error) throw error
    },

    async deleteRow(opts: {
      schema?: string
      table: string
      match: Record<string, any>
    }): Promise<void> {
      const { error } = await table(opts.schema, opts.table).delete().match(opts.match)
      if (error) throw error
    },
  }
}

