import type { SupabaseClient } from '@supabase/supabase-js'

import type {
  IntrospectedColumn,
  IntrospectedTable,
} from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/introspection-types'

/**
 * Introspect a database over PostgREST — no Management API, no arbitrary SQL.
 *
 * PostgREST serves an OpenAPI 2.0 (Swagger) document at the REST root that
 * describes every exposed table/view, its columns (type, format, default,
 * enum, nullability) and marks primary/foreign keys in each column's
 * `description`. We parse that into the normalized `IntrospectedTable` shape.
 *
 * Limitations vs pg-meta: only API-exposed schemas are visible (typically
 * `public`), and RLS state / generated-column flags are not reported (left
 * null / false). Acceptable for the table + row-editor surface.
 */
export async function introspectViaPostgrest(
  supabase: SupabaseClient
): Promise<IntrospectedTable[]> {
  // `rest.url` / `rest.headers` are protected on the client but present at
  // runtime; they carry the apikey + auth headers we need for the spec request.
  const rest = (supabase as any).rest
  const restUrl: string = rest?.url
  const headers: Record<string, string> = rest?.headers ?? {}

  if (!restUrl) {
    throw new Error('Could not resolve the PostgREST URL from the Supabase client.')
  }

  const response = await fetch(`${restUrl}/`, { headers })
  if (!response.ok) {
    throw new Error(`Failed to load the PostgREST schema (${response.status}).`)
  }

  const spec = await response.json()
  const definitions: Record<string, any> = spec?.definitions ?? {}

  const tables: IntrospectedTable[] = Object.entries(definitions).map(([tableName, def]) => {
    const properties: Record<string, any> = def?.properties ?? {}
    const required: string[] = Array.isArray(def?.required) ? def.required : []

    const columns: IntrospectedColumn[] = Object.entries(properties).map(([name, prop]) => {
      const enums: string[] = Array.isArray(prop?.enum) ? prop.enum : []
      const defaultValue = prop?.default ?? null
      const rawFormat: string = prop?.format ?? prop?.type ?? 'text'

      let data_type: string
      if (prop?.type === 'array') {
        data_type = 'ARRAY'
      } else if (enums.length > 0) {
        data_type = 'USER-DEFINED'
      } else {
        data_type = rawFormat
      }

      const isIdentity =
        typeof defaultValue === 'string' &&
        (defaultValue.includes('nextval(') || defaultValue.toUpperCase().includes('GENERATED'))

      return {
        name,
        data_type,
        format: rawFormat,
        // PostgREST marks a column `required` when it is NOT NULL without a
        // default; treat everything else as nullable (best-effort).
        is_nullable: !required.includes(name),
        is_identity: isIdentity,
        is_generated: false,
        is_updatable: !isIdentity,
        default_value: defaultValue,
        enums,
        comment: null,
      }
    })

    const primary_keys = Object.entries(properties)
      .filter(([, prop]) => {
        const description: string = prop?.description ?? ''
        return description.includes('<pk/>') || /primary key/i.test(description)
      })
      .map(([name]) => ({ name }))

    return {
      id: tableName,
      schema: 'public',
      name: tableName,
      columns,
      primary_keys,
      live_rows_estimate: null,
      rls_enabled: null,
      comment: null,
    }
  })

  return tables.sort((a, b) => a.name.localeCompare(b.name))
}

import type {
  IntrospectedColumn,
  IntrospectedTable,
} from '@/registry/default/platform/platform-kit-nextjs/lib/adapter/introspection-types'

// Minimal shape of supalite's `GET /_system/introspect` response. Only the
// fields we consume are typed; the endpoint returns more.
interface SupaliteTableInfo {
  name: string
  schema: string
  type: 'table' | 'view'
  rows: number
}
interface SupaliteColumnInfo {
  table: string
  name: string
  type: string
  nullable: boolean
  default_value: string | null
  is_primary_key: boolean
  schema: string
  ordinal_position: number
  is_identity: boolean
  is_generated?: boolean
  pg_type?: string
}
interface SupalitePrimaryKeyInfo {
  table: string
  columns: string[]
  schema: string
}
interface SupaliteCustomType {
  schema: string
  type: string
  kind: 'enum' | 'composite'
  values?: string[]
}
interface SupaliteCommentInfo {
  schema: string
  table: string
  column?: string
  text: string
}
export interface SupaliteIntrospectResult {
  tables: SupaliteTableInfo[]
  columns: SupaliteColumnInfo[]
  primary_keys: SupalitePrimaryKeyInfo[]
  custom_types: SupaliteCustomType[]
  comments?: SupaliteCommentInfo[]
}

/**
 * Map supalite's `/_system/introspect` payload into the normalized
 * `IntrospectedTable[]` the UI consumes. Only base tables are returned; RLS
 * state is unavailable and reported as null.
 */
export function mapIntrospectResult(
  result: SupaliteIntrospectResult,
  schemas?: string[]
): IntrospectedTable[] {
  const enumsByType = new Map<string, string[]>()
  for (const t of result.custom_types ?? []) {
    if (t.kind === 'enum' && t.values) {
      enumsByType.set(t.type, t.values)
      enumsByType.set(`${t.schema}.${t.type}`, t.values)
    }
  }

  const commentFor = (schema: string, table: string, column?: string): string | null => {
    const match = (result.comments ?? []).find(
      (c) => c.schema === schema && c.table === table && c.column === column
    )
    return match?.text ?? null
  }

  return result.tables
    .filter((t) => t.type === 'table')
    .filter((t) => !schemas || schemas.length === 0 || schemas.includes(t.schema))
    .map((table) => {
      const cols = result.columns
        .filter((c) => c.table === table.name && c.schema === table.schema)
        .sort((a, b) => a.ordinal_position - b.ordinal_position)

      const columns: IntrospectedColumn[] = cols.map((c) => {
        const enums = enumsByType.get(c.pg_type ?? c.type) ?? enumsByType.get(c.type) ?? []
        const is_generated = c.is_generated ?? false
        return {
          name: c.name,
          data_type: enums.length > 0 ? 'USER-DEFINED' : c.type,
          format: c.pg_type ?? c.type,
          is_nullable: c.nullable,
          is_identity: c.is_identity,
          is_generated,
          is_updatable: !is_generated && !c.is_identity,
          default_value: c.default_value,
          enums,
          comment: commentFor(table.schema, table.name, c.name),
        }
      })

      const pkRecord = result.primary_keys.find(
        (pk) => pk.table === table.name && pk.schema === table.schema
      )
      const primary_keys = pkRecord
        ? pkRecord.columns.map((name) => ({ name }))
        : cols.filter((c) => c.is_primary_key).map((c) => ({ name: c.name }))

      return {
        id: `${table.schema}.${table.name}`,
        schema: table.schema,
        name: table.name,
        columns,
        primary_keys,
        live_rows_estimate: typeof table.rows === 'number' ? table.rows : null,
        rls_enabled: null,
        comment: commentFor(table.schema, table.name),
      }
    })
    .sort((a, b) => a.name.localeCompare(b.name))
}

export enum LogsTableName {
  FN_EDGE = 'function_edge_logs',
  AUTH = 'auth_logs',
  POSTGRES = 'postgres_logs',
  REALTIME = 'realtime_logs',
  STORAGE = 'storage_logs',
  PG_CRON = 'pg_cron_logs',
  EDGE = 'edge_logs',
  FUNCTIONS = 'function_logs',
  POSTGREST = 'postgrest_logs',
  SUPAVISOR = 'supavisor_logs',
  PGBOUNCER = 'pgbouncer_logs',
  PG_UPGRADE = 'pg_upgrade_logs',
}

const genCrossJoinUnnests = (table: LogsTableName) => {
  switch (table) {
    case LogsTableName.EDGE:
      return `cross join unnest(metadata) as m
  cross join unnest(m.request) as request
  cross join unnest(m.response) as response`
    case LogsTableName.POSTGRES:
      return `cross join unnest(metadata) as m
  cross join unnest(m.parsed) as parsed`
    case LogsTableName.FUNCTIONS:
      return `cross join unnest(metadata) as metadata`
    case LogsTableName.AUTH:
      return `cross join unnest(metadata) as metadata`
    case LogsTableName.FN_EDGE:
      return `cross join unnest(metadata) as m
  cross join unnest(m.response) as response
  cross join unnest(m.request) as request`
    case LogsTableName.SUPAVISOR:
      return `cross join unnest(metadata) as m`
    default:
      return ''
  }
}

export const genDefaultQuery = (table: LogsTableName, limit: number = 100) => {
  const joins = genCrossJoinUnnests(table)
  const orderBy = 'order by timestamp desc'

  switch (table) {
    case LogsTableName.EDGE:
      return `select id, ${table}.timestamp, event_message, request.method, request.path, request.search, response.status_code
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.POSTGRES:
      return `select ${table}.timestamp, id, event_message, parsed.error_severity, parsed.detail, parsed.hint
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.FUNCTIONS:
      return `select id, ${table}.timestamp, event_message, metadata.event_type, metadata.function_id, metadata.level
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.AUTH:
      return `select id, ${table}.timestamp, event_message, metadata.level, metadata.status, metadata.path, metadata.msg as msg, metadata.error
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.FN_EDGE:
      return `select id, ${table}.timestamp, event_message, response.status_code, request.method, m.function_id, m.execution_time_ms, m.deployment_id, m.version
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.SUPAVISOR:
      return `select id, ${table}.timestamp, event_message
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.PG_UPGRADE:
      return `select id, ${table}.timestamp, event_message
from ${table}
${joins}
${orderBy}
limit ${limit}`

    case LogsTableName.PG_CRON:
      return `select postgres_logs.timestamp, id, event_message, parsed.error_severity, parsed.query
from postgres_logs
cross join unnest(metadata) as m
cross join unnest(m.parsed) as parsed
where (parsed.application_name = 'pg_cron' OR event_message LIKE '%cron job%')
${orderBy}
limit ${limit}`

    default:
      return `select id, ${table}.timestamp, event_message
from ${table}
${joins}
${orderBy}
limit ${limit}`
  }
}

import createClient, { type Client } from 'openapi-fetch'

import type { paths } from '@/registry/default/platform/platform-kit-nextjs/lib/management-api-schema'

export type ManagementApiClient = Client<paths>

/**
 * Build an openapi-fetch client for the Supabase Management API.
 *
 * The kit ships no proxy — the consumer points `baseUrl` at their own trusted
 * transport (e.g. a serverless route that injects the Management API token and
 * enforces per-project permissions) so the token never reaches the browser.
 */
export function createManagementApiClient(opts: {
  baseUrl: string
  headers?: Record<string, string>
  fetch?: typeof fetch
}): ManagementApiClient {
  return createClient<paths>({
    baseUrl: opts.baseUrl,
    headers: opts.headers,
    fetch: opts.fetch,
  })
}

import { stripIndent } from 'common-tags'

import { columnsSql, extensionsSql, tablesSql } from './sql'

export const SYSTEM_SCHEMAS = [
  'information_schema',
  'pg_catalog',
  'pg_toast',
  '_timescaledb_internal',
]

/**
 * Generates the SQL query to list tables in the database.
 */
export function listTablesSql(schemas: string[] = []) {
  let sql = stripIndent`
    with
      tables as (${tablesSql}),
      columns as (${columnsSql})
    select
      *,
      ${coalesceRowsToArray('columns', 'columns.table_id = tables.id')}
    from tables
  `

  sql += '\n'

  if (schemas.length > 0) {
    sql += `where schema in (${schemas.map((s) => `'${s}'`).join(',')})`
  } else {
    sql += `where schema not in (${SYSTEM_SCHEMAS.map((s) => `'${s}'`).join(',')})`
  }

  return sql
}

/**
 * Generates the SQL query to list all extensions in the database.
 */
export function listExtensionsSql() {
  return extensionsSql
}

/**
 * Generates a SQL segment that coalesces rows into an array of JSON objects.
 */
export const coalesceRowsToArray = (source: string, filter: string) => {
  return stripIndent`
    COALESCE(
      (
        SELECT
          array_agg(row_to_json(${source})) FILTER (WHERE ${filter})
        FROM
          ${source}
      ),
      '{}'
    ) AS ${source}
  `
}

/**
 * Routing helpers for the manager dialog. Navigation is driven by wouter over
 * an in-memory location (see `components/supabase-manager/index.tsx`), so the
 * widget is fully self-contained and never touches the browser URL.
 */

export const TOP_LEVEL_TITLES: Record<string, string> = {
  database: 'Database',
  storage: 'Storage',
  auth: 'Authentication',
  users: 'Users',
  secrets: 'Secrets',
  logs: 'Logs',
  suggestions: 'Suggestions',
}

export interface Crumb {
  title: string
  path: string
}

function capitalize(value: string) {
  return value.charAt(0).toUpperCase() + value.slice(1)
}

/** Build breadcrumb entries from the current in-memory location. */
export function buildBreadcrumbs(location: string): Crumb[] {
  const segments = location.split('/').filter(Boolean)
  if (segments.length === 0) return []

  const [root, ...rest] = segments
  const crumbs: Crumb[] = [{ title: TOP_LEVEL_TITLES[root] ?? capitalize(root), path: `/${root}` }]

  if (root === 'database') {
    if (rest[0] === 'query') {
      crumbs.push({ title: 'Talk to your database', path: '/database/query' })
    } else if (rest[0]) {
      const table = decodeURIComponent(rest[0])
      crumbs.push({ title: table, path: `/database/${rest[0]}` })
      if (rest[1] === 'edit') {
        crumbs.push({ title: 'Editing row', path: `/database/${rest[0]}/edit` })
      }
    }
  } else if (root === 'auth' && rest[0]) {
    const provider = decodeURIComponent(rest[0])
    crumbs.push({ title: `${capitalize(provider)} Provider Settings`, path: `/auth/${rest[0]}` })
  }

  return crumbs
}

import z from 'zod'

export const secretsSchema = z
  .object({
    secrets: z.array(
      z.object({
        name: z
          .string()
          .min(1, 'Secret name is required.')
          .regex(
            /^[a-zA-Z_][a-zA-Z0-9_]*$/,
            'Must contain letters, numbers, and underscores, starting with a letter or underscore.'
          ),
        value: z.string().min(1, 'Secret value is required.'),
      })
    ),
  })
  .describe('Secrets schema for managing environment variables.')

export type SecretsSchema = z.infer<typeof secretsSchema>

export const deleteSecretsSchema = z
  .object({
    secretNames: z
      .array(z.string().min(1, 'Secret name cannot be empty.'))
      .min(1, 'At least one secret name is required.'),
  })
  .describe('Schema for deleting secrets by name.')
export type DeleteSecretsSchema = z.infer<typeof deleteSecretsSchema>
